mapper.select:
select * from eg_ta_reclassification_detail etrd where to_char(reclassification_month, 'YYYY-MM') = #{param.reclassificationMonth}
and exists (select 1 from eg_ta_reclassification_upload_record etrur where etrur.batch_id = #{param.batchId}
and etrd.reclassification_month = etrur.reclassification_month
and etrd.contract_code = etrur.contract_code
and etrd.ebank_batch_no = etrur.ebank_batch_no)
